void abort(void);
void exit(int);

int w[2][2];

void f(void) {
  int i, j;

  for (i = 0; i < 2; i++)
    for (j = 0; j < 2; j++)
      if (i == j)
        w[i][j] = 1;
}

int main(void) {
  f();
  if (w[0][0] != 1 || w[1][1] != 1 || w[1][0] != 0 || w[0][1] != 0)
    abort();
  exit(0);
}



